package dev.interview.ledger;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.sql.PreparedStatement;import java.time.OffsetDateTime;import java.util.Map;
@Service public class ScaleDatasetService{
 private final JdbcTemplate db;ScaleDatasetService(JdbcTemplate d){db=d;}
 @Transactional public Map<String,Object> generate(ApiModels.ScaleRequest r){long started=System.nanoTime();int chunk=10_000;OffsetDateTime now=OffsetDateTime.now();for(int base=0;base<r.transactions();base+=chunk){int from=base,size=Math.min(chunk,r.transactions()-base);db.batchUpdate("insert into ledger_entries values(?,?,?,?,?,?,?,?,?,?)",new org.springframework.jdbc.core.BatchPreparedStatementSetter(){public int getBatchSize(){return size;}public void setValues(PreparedStatement p,int i)throws java.sql.SQLException{int n=from+i;line(p,"scale_debit_"+n,"scale_j_"+n,"stripe_receivable",r.currency(),1000,"CAPTURE","scale_pi_"+n,now);}});db.batchUpdate("insert into ledger_entries values(?,?,?,?,?,?,?,?,?,?)",new org.springframework.jdbc.core.BatchPreparedStatementSetter(){public int getBatchSize(){return size;}public void setValues(PreparedStatement p,int i)throws java.sql.SQLException{int n=from+i;line(p,"scale_credit_"+n,"scale_j_"+n,"customer_funds",r.currency(),-1000,"CAPTURE","scale_pi_"+n,now);}});db.batchUpdate("insert into external_transactions values(?,?,?,?,?,?,?,?)",new org.springframework.jdbc.core.BatchPreparedStatementSetter(){public int getBatchSize(){return size;}public void setValues(PreparedStatement p,int i)throws java.sql.SQLException{int n=from+i;long amount=n%100<r.mismatchPercent()?999:1000;p.setString(1,"scale_tx_"+n);p.setString(2,"scale_pi_"+n);p.setLong(3,amount);p.setString(4,r.currency());p.setString(5,"AVAILABLE");p.setObject(6,now);p.setString(7,Hashing.sha256("scale_tx_"+n+amount));p.setString(8,"STRIPE");}});}
 update("stripe_receivable",r.currency(),1000L*r.transactions(),now);update("customer_funds",r.currency(),-1000L*r.transactions(),now);return Map.of("transactions",r.transactions(),"ledgerEntries",2L*r.transactions(),"mismatchPercent",r.mismatchPercent(),"elapsedMs",(System.nanoTime()-started)/1_000_000);}
 private void line(PreparedStatement p,String id,String journal,String account,String currency,long amount,String type,String ref,OffsetDateTime now)throws java.sql.SQLException{p.setString(1,id);p.setString(2,journal);p.setString(3,account);p.setString(4,currency);p.setLong(5,amount);p.setString(6,type);p.setString(7,ref);p.setString(8,ref);p.setString(9,"generated scale dataset");p.setObject(10,now);}private void update(String a,String c,long amount,OffsetDateTime now){int n=db.update("update balance_projection set balance=balance+?,version=version+1,updated_at=? where account_id=? and currency=?",amount,now,a,c);if(n==0)db.update("insert into balance_projection values(?,?,?,?,?)",a,c,amount,1,now);}
}
